// n8n Code node: "Parse and filter"  (mode: Run Once for All Items)
//
// Input : one item per LinkedIn job-alert email from the Gmail Trigger.
// Output: one item per job that matches the target roles and is not already in
//         the tracker sheet, carrying a ready-to-send Claude request body.
//
// Reads two upstream nodes by name:
//   $('Gmail Trigger')  - the alert emails
//   $('Load tracker')   - every row already in the Google Sheet
// Rename either node in the canvas and you must rename it here too.

const PROFILE = "## Target roles\n\n- D2C Operations Manager / eCommerce Operations Manager\n- Supply Chain Manager / Supply Chain Lead\n\n## Summary\n\nOperations and Inventory Manager with over 4 years of experience in supply chain\noperations, inventory control, and domestic and international dispatch across\nhealthcare, D2C e-commerce, and marketplace businesses. Consistently maintains\n98% or better on-time dispatch SLA while managing logistics through Shiprocket\nand DHL. Experienced Zoho CRM administrator supporting customer lifecycle\nmanagement, with proven strength in demand forecasting, warehouse\nreconciliation, MIS reporting, and leading inventory and dispatch teams.\n\nBased in Chandigarh, India. Open to relocation.\n\n## Skills\n\n- Supply chain and logistics: inventory management, demand forecasting, domestic\n  dispatch (Shiprocket), international logistics (DHL), customs documentation,\n  SLA and TAT management, quick-commerce operations, D2C operations, warehouse\n  reconciliation, reorder point planning, cycle counting\n- Systems and CRM: Zoho CRM administration, Zoconut, Shopify, Unicommerce,\n  HubSpot, Oracle\n- Data and reporting: Power BI, MIS dashboards, advanced Microsoft Excel,\n  inventory reconciliation\n- Automation and design: AI-assisted workflow automation, SOP development,\n  process optimization, Figma prototyping\n- Leadership: team management, task allocation, vendor coordination, escalation\n  management\n\n## Experience\n\nGLEUHR Wellness, Chandigarh — Operations Manager, Inventory and Dispatch\n(May 2026 to present)\n- Owns end-to-end physical and system inventory across clinic and complementary\n  product categories, including warehouse reconciliation and cycle counts.\n- Controls reorder points for fast-moving SKUs, eliminating stockouts while\n  holding reorder spend within budget.\n- Directs domestic dispatch through Shiprocket and international freight,\n  tracking, and customs documentation through DHL.\n- Maintains a 24 to 48 hour dispatch SLA across web, sales, and B2B orders.\n- Produces daily, weekly, and monthly MIS on inventory accuracy, RTO receipts,\n  and cycle counts.\n- Leads a 4-member inventory and dispatch team; reduced expiry write-offs.\n\nSova Health, Gurugram — Team Lead, Operations and Unicommerce Dispatch System\n(January 2024 to April 2026)\n- Scaled quick-commerce revenue from roughly INR 50 lakh to INR 4.3 crore in\n  8 months across Blinkit, Zepto, and Swiggy Instamart.\n- Built an automation that cut order-processing turnaround from roughly 48 hours\n  to around 10 minutes.\n- Dedicated Zoho Manager: customized Zoho CRM and Zoconut workflows for patient\n  lifecycle tracking and follow-up automation, sustaining CSAT of 95% or higher.\n- Managed 1,600+ client accounts and PAN-India dispatch of gut microbiome\n  diagnostic kits at 98% or better on-time SLA.\n- Ran Shopify order processing and Amazon/Flipkart marketplace operations,\n  including inventory reconciliation and refunds.\n\nPolicy Bazaar, Gurugram — Relationship Manager, Client Relations\n(May 2021 to May 2022)\n- Client onboarding, primary contact for SLA governance and issue resolution.\n- HRMIS reporting across client accounts.\n\n## Education\n\n- MBA, Human Resources and Marketing — Chandigarh University (2022-2024)\n- BBA (Hons), Marketing and Banking — Lovely Professional University (2019-2022)\n";

// A job must match one of these to survive.
const WANTED = [
  /\b(d2c|direct[- ]to[- ]consumer|e-?commerce|ecom)\b[\s\S]{0,30}\boperations?\b/i,
  /\boperations?\b[\s\S]{0,30}\b(d2c|direct[- ]to[- ]consumer|e-?commerce|ecom)\b/i,
  /\bsupply chain\b[\s\S]{0,30}\b(manager|lead|head|specialist)\b/i,
  /\b(manager|lead|head)\b[\s\S]{0,30}\bsupply chain\b/i,
];

// ...and must not match any of these. Seniority guards on both ends: roles far
// below the current one are a step back, roles far above will not shortlist.
const REJECT = [
  /\b(intern|internship|trainee|apprentice|fresher)\b/i,
  /\b(executive assistant|assistant to)\b/i,
  /\b(vp|vice president|director|cxo|chief)\b/i,
  /\b(driver|picker|packer|loader|helper)\b/i,
];

const decodeEntities = (s) => s
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&(middot|bull);/g, '·')
  .replace(/&(ndash|mdash);/g, '-')
  .replace(/&#(\d+);/g, (_, d) => String.fromCharCode(Number(d)))
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCharCode(parseInt(h, 16)));

const stripTags = (s) => decodeEntities(String(s).replace(/<[^>]*>/g, ' '))
  .replace(/\s+/g, ' ')
  .trim();

// The Gmail node returns the body in a different shape depending on its version
// and its "format" option, so look in every place it might be.
function extractHtml(item) {
  const j = item.json || {};
  if (typeof j.html === 'string' && j.html) return j.html;
  if (typeof j.textAsHtml === 'string' && j.textAsHtml) return j.textAsHtml;

  const fromB64 = (data) => Buffer
    .from(String(data).replace(/-/g, '+').replace(/_/g, '/'), 'base64')
    .toString('utf8');

  const walk = (part) => {
    if (!part) return '';
    if (part.mimeType === 'text/html' && part.body && part.body.data) {
      return fromB64(part.body.data);
    }
    for (const child of part.parts || []) {
      const found = walk(child);
      if (found) return found;
    }
    return '';
  };
  const fromPayload = walk(j.payload);
  if (fromPayload) return fromPayload;

  if (typeof j.text === 'string' && j.text) return j.text;
  return '';
}

// LinkedIn alert emails link each job as /jobs/view/<id> (usually under the
// /comm/ tracking prefix) with the job title as the anchor text. The company
// name sits in the markup just after the anchor, which is the fragile part of
// this parser - check this node's output on the first real run.
function parseJobs(html) {
  const jobs = [];
  const anchor = /<a\b[^>]*href="([^"]*?\/jobs\/view\/(\d+)[^"]*)"[^>]*>([\s\S]*?)<\/a>/gi;
  let m;
  while ((m = anchor.exec(html)) !== null) {
    const title = stripTags(m[3]);
    if (!title || /^(view|apply|see|show)\b/i.test(title)) continue;

    // Stop at the next job link so one posting cannot swallow the next one's
    // text, backing up to that link's opening tag so no half tag survives.
    const nextLink = html.indexOf('/jobs/view/', anchor.lastIndex);
    const end = nextLink === -1
      ? Math.min(anchor.lastIndex + 800, html.length)
      : Math.max(html.lastIndexOf('<', nextLink), anchor.lastIndex);
    const [company = '', location = ''] = stripTags(html.slice(anchor.lastIndex, end))
      .split('·')
      .map((s) => s.trim())
      .filter((s) => s && !/^(view|see|apply|show)\b/i.test(s));

    jobs.push({
      jobId: m[2],
      title,
      company: company.slice(0, 120),
      location: location.slice(0, 120),
      // Drop the tracking query string; the bare permalink is what gets stored.
      url: `https://www.linkedin.com/jobs/view/${m[2]}/`,
    });
  }
  return jobs;
}

function wanted(title) {
  if (REJECT.some((re) => re.test(title))) return false;
  return WANTED.some((re) => re.test(title));
}

function claudeBody(job) {
  const system = [
    'You screen job postings for one candidate and draft the opening of an',
    'application note. Judge fit only from the candidate profile below.',
    '',
    'Rules you must not break:',
    '- Use only facts stated in the profile. Never invent an employer, a metric,',
    '  a tool, a certification, or a responsibility that is not written there.',
    '- If the posting needs something the profile does not show, put it in gaps',
    '  rather than papering over it.',
    '- You are given only the job title, company and location, not the full job',
    '  description. Score what those support and no more; when the title is',
    '  ambiguous, score it lower rather than guessing generously.',
    '- The opening is at most 120 words, first person, plain sentences, no',
    '  greeting and no sign-off.',
    '',
    '--- CANDIDATE PROFILE ---',
    PROFILE,
  ].join('\n');

  const user = [
    `Job title: ${job.title}`,
    `Company: ${job.company || 'unknown'}`,
    `Location: ${job.location || 'unknown'}`,
    `Posting: ${job.url}`,
  ].join('\n');

  return {
    model: 'claude-opus-5',
    max_tokens: 2000,
    system,
    messages: [{ role: 'user', content: user }],
    output_config: {
      // Triage, not deep reasoning - low effort keeps the per-job cost down.
      effort: 'low',
      format: {
        type: 'json_schema',
        schema: {
          type: 'object',
          properties: {
            fit_score: { type: 'integer', minimum: 1, maximum: 10 },
            verdict: { type: 'string' },
            strengths: { type: 'array', items: { type: 'string' } },
            gaps: { type: 'array', items: { type: 'string' } },
            opening: { type: 'string' },
          },
          required: ['fit_score', 'verdict', 'strengths', 'gaps', 'opening'],
          additionalProperties: false,
        },
      },
    },
  };
}

// Every job id the tracker has already seen, whatever the column is called.
const seen = new Set(
  $('Load tracker').all()
    .map((row) => String((row.json || {}).JobId ?? (row.json || {}).jobId ?? '').trim())
    .filter(Boolean),
);

const out = [];
for (const email of $('Gmail Trigger').all()) {
  for (const job of parseJobs(extractHtml(email))) {
    if (seen.has(job.jobId)) continue;   // already tracked
    if (!wanted(job.title)) continue;    // not a target role
    seen.add(job.jobId);                 // and not twice within this batch
    out.push({ json: { ...job, claudeBody: claudeBody(job) } });
  }
}

return out;

// n8n Code node: "Read scores"  (mode: Run Once for All Items)
//
// Turns each Claude response into one flat row matching the tracker sheet's
// column headers, and drops anything below the score threshold.
//
// The HTTP Request node replaces the item body with Claude's response, so the
// job fields are read back from 'Parse and filter' by index - the HTTP node
// emits one item per input item, in order.

const MIN_SCORE = 7;

const responses = $input.all();
const jobs = $('Parse and filter').all();

const today = new Date().toISOString().slice(0, 10);
const rows = [];

// Keep failures in the same column shape as scored rows, so the tracker never
// gets a half-empty row and the digest can still report what went wrong.
const failed = (job, error) => ({
  json: {
    Date: today,
    Company: job.company || '',
    Title: job.title || '',
    Location: job.location || '',
    JobId: job.jobId || '',
    URL: job.url || '',
    FitScore: '',
    Verdict: '',
    Gaps: '',
    Opening: '',
    Status: 'scoring failed',
    error,
  },
});

responses.forEach((res, i) => {
  const job = (jobs[i] || {}).json || {};
  const body = res.json || {};

  // With thinking on, the JSON answer is not always the first content block.
  const blocks = Array.isArray(body.content) ? body.content : [];
  const text = blocks.filter((b) => b && b.type === 'text').map((b) => b.text).join('');

  // Surfaced in the digest rather than silently dropped.
  if (body.stop_reason === 'refusal' || !text) {
    rows.push(failed(job, `no usable response (stop_reason: ${body.stop_reason || 'none'})`));
    return;
  }

  let scored;
  try {
    scored = JSON.parse(text);
  } catch (e) {
    rows.push(failed(job, `unparseable response: ${text.slice(0, 200)}`));
    return;
  }

  if (Number(scored.fit_score) < MIN_SCORE) return;

  rows.push({
    json: {
      Date: today,
      Company: job.company || '',
      Title: job.title || '',
      Location: job.location || '',
      JobId: job.jobId || '',
      URL: job.url || '',
      FitScore: Number(scored.fit_score),
      Verdict: String(scored.verdict || ''),
      Gaps: (scored.gaps || []).join('; '),
      Opening: String(scored.opening || ''),
      Status: 'ready',
    },
  });
});

// Best first, so the digest leads with the roles worth opening.
return rows.sort((a, b) => (b.json.FitScore || 0) - (a.json.FitScore || 0));

// n8n Code node: "Build digest"  (mode: Run Once for All Items)
//
// Collapses every scored job into the single email you actually read.
// Returns no items when nothing scored high enough, which stops the Gmail node
// from sending an empty digest.

const rows = $('Read scores').all().map((i) => i.json);
const jobs = rows.filter((r) => !r.error);
const failures = rows.filter((r) => r.error);

if (!jobs.length && !failures.length) return [];

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const card = (j) => `
  <div style="border:1px solid #d6dbe1;border-radius:6px;padding:14px;margin:0 0 14px">
    <div style="font:600 16px/1.3 system-ui,sans-serif;color:#1f3d5c">
      ${esc(j.Title)} — ${esc(j.Company)}
    </div>
    <div style="font:13px/1.5 system-ui,sans-serif;color:#4a5560;margin:2px 0 10px">
      ${esc(j.Location)} &nbsp;·&nbsp; fit ${esc(j.FitScore)}/10 &nbsp;·&nbsp; ${esc(j.Verdict)}
    </div>
    ${j.Gaps ? `<div style="font:13px/1.5 system-ui,sans-serif;color:#8a4b2a;margin:0 0 10px">
      Gaps: ${esc(j.Gaps)}</div>` : ''}
    <div style="font:14px/1.6 system-ui,sans-serif;color:#1a1a1a;background:#f6f8fa;
                border-radius:4px;padding:10px;white-space:pre-wrap">${esc(j.Opening)}</div>
    <div style="margin-top:12px">
      <a href="${esc(j.URL)}" style="font:600 14px system-ui,sans-serif;color:#1f3d5c">
        Open and apply &rarr;</a>
    </div>
  </div>`;

const problems = failures.length ? `
  <p style="font:13px/1.5 system-ui,sans-serif;color:#8a4b2a">
    ${failures.length} posting(s) could not be scored:
    ${esc(failures.map((f) => `${f.Title || f.JobId}: ${f.error}`).join(' | '))}
  </p>` : '';

const html = `
  <div style="max-width:640px;margin:0 auto">
    <p style="font:14px/1.5 system-ui,sans-serif;color:#4a5560">
      ${jobs.length} matching role${jobs.length === 1 ? '' : 's'} from today's LinkedIn alerts.
      Openings below are drafts — read before sending.
    </p>
    ${jobs.map(card).join('')}
    ${problems}
  </div>`;

const subject = jobs.length
  ? `${jobs.length} job${jobs.length === 1 ? '' : 's'} to apply to — ${jobs[0].Title} at ${jobs[0].Company}`
  : 'LinkedIn job alerts: nothing scored, but something failed';

return [{ json: { subject, html } }];
